from pathlib import Path
import csv,json,subprocess,sys
R=Path(__file__).resolve().parents[2];O=Path(sys.argv[1]);subprocess.run([sys.executable,str(R/'Benchmarks/water-network/write_report.py'),str(O)],check=True)
P=R/'Benchmarks/water-network/REPORT.md';s=P.read_text();after=json.loads((O/'functional-after-fix/checks.json').read_text())['jobs'];jobs=json.loads((O/'network-after-fix/manifest.json').read_text());rows=list(csv.DictReader((O/'network-after-fix/summary.csv').open()));spot=list(csv.DictReader((O/'water-after-fix/summary.csv').open()));commit=subprocess.check_output(['git','rev-parse','fix/water-buoyancy-rollback-20261030'],cwd=R,text=True).strip()
def table(h,rs):return '\n'.join(['| '+' | '.join(h)+' |','|'+'|'.join(['---']*len(h))+'|']+['| '+' | '.join(map(str,r))+' |' for r in rs])
def f(v):return f'{float(v):.3f}'
s=s.replace('All engine implementation sources are unchanged; test library paths were adapted to this isolated checkout.',f'Baseline measurements use that revision. Final validation also tests rollback fix `{commit}`; native implementation is unchanged. Test library paths were adapted to this isolated checkout.')
s=s.replace('Networking correctness checks pass across the engine features listed in COVERAGE.md,', 'The existing networking tests passed, and an added regression exposed and now verifies a buoyancy rollback fix. Final correctness checks pass across the engine features listed in COVERAGE.md,')
section=['## Buoyancy rollback fix and final validation','',f'Fix commit: `{commit}`. Normal physics applies water forces before stepping Jolt; rollback previously stepped Jolt without those forces. In a new 12-tick test that caused 0.202 m position / 1.872 m/s velocity error in flat water and 0.174 m / 1.610 m/s with waves. Rollback now applies buoyancy at each historical simulation tick, rather than using the current scene time. Four final regressions cover flat/wavy water for both owned and predicted server bodies; all match forward simulation exactly in position and velocity.','',f'- **Complete listed CPU suite after the fix: 53 passed, 0 failed**, no retries.',f"- **Focused final validation: {sum(j['pass_checks'] for j in after)} checks across {len(after)} runs, {sum(not j['pass'] for j in after)} failed runs**, including the Maps fixture omitted from the repository’s default 53-fixture list. These overlap the complete suite.",f"- **Affected/network stress reruns: {len(set(j['case'] for j in jobs))} scenarios, {len(jobs)} processes, {sum(not j['valid'] for j in jobs)} failed process validations**. Includes default floating-body loads, both impairment settings, 32-player optimized and mixed reliable state traffic.",'','Patched network results (early moving phase; same measurement method as the baseline table below):','']
rs=[]
for a in rows:
 if a['phase']=='moving':rs.append([a['case'],f(float(a['client_wire_received_mean_Bps'])/1024),f(float(a['server_wire_sent_Bps'])*8/1e6),f(a['fixed_mean_ms']),f(a['fixed_worst_ms']),f(a['server_hz']),f(a['max_truth_error_m']),a['max_client_rollbacks'],a['passed']])
section += [table(['Scenario','Client ↓ KiB/s','Server ↑ Mbit/s','Fixed mean ms','Worst ms','Server Hz','Final error m','Max rollbacks','Pass'],rs),'', 'Patched water spot checks (three fresh processes per workload):','',table(['Case','Mode','Count','Water p95 ms','Total CPU p95 ms','Frame p95 ms'],[[a['case'],a['mode'],a['count'],f(a['water_p95_ms']),f(a['total_p95_ms']),f(a['frame_p95_ms'])] for a in spot]),'','The complete water matrix below is from the baseline; these spot checks validate the unchanged forward-water path after the rollback fix. Additional shell measurements use the fixed engine. The network section below retains all 28 baseline scenarios so the smaller post-fix rerun is not presented as a rerun of every configuration.','']
s=s.replace('## Correctness and coverage','\n'.join(section)+'\n## Baseline correctness and coverage')
s=s.replace('## Network bandwidth\n','## Network bandwidth — full baseline matrix\n')
s=s.replace('No engine implementation changes were needed for the completed passing measurements.', 'Engine changes are limited to the buoyancy rollback fix above; four regression checks were added to Tests/Water.')
s=s.replace('`functional/` and `validation/`: assertions, fixture summary, native build/shader logs and feature traffic.','`functional/`, `functional-after-fix/` and `validation/`: assertions, before/after full fixture summaries, failing/passing rollback regression logs, native build/shader logs and feature traffic.')
s=s.replace('- `network/`: per-process raw traffic, manifests, and phase summaries.', '- `network/`: all baseline scenarios. `network-after-fix/`: eight targeted final scenarios. Both retain per-process traffic, manifests and phase summaries.\n- `water-after-fix/`: targeted forward-water timing checks on the fixed engine.')
s += '\n## Plots and visual verification\n\n' + f'![CPU scaling](../results/{O.name}/plots/water-cpu-scaling.png)\n\n![Network bandwidth](../results/{O.name}/plots/network-bandwidth.png)\n\n' + f'[Realistic ocean](../results/{O.name}/screenshots/ocean-real.png), [low-poly ocean](../results/{O.name}/screenshots/ocean-low.png), and [underwater](../results/{O.name}/screenshots/underwater-real.png) screenshots were captured and visually checked. The scene render target is fixed; screenshots reflect the window manager’s displayed backbuffer size.\n\nThe initial Maps launch used the wrong working directory and could not read its test model. The corrected run passed all 49 checks, including model loading and chunked map transfer. Both attempts are retained.\n\n[Draft PR #4](https://github.com/LazyAlgorithm/Tessera/pull/4) contains the rollback fix and regression tests; it has not been merged into main.\n'
P.write_text(s);(O/'REPORT.md').write_text(s.replace('[README.md](README.md)','[README.md](../../water-network/README.md)').replace('[COVERAGE.md](COVERAGE.md)','[COVERAGE.md](../../water-network/COVERAGE.md)').replace(f'../results/{O.name}/',''));print('Final report written')
